def spfa(adj, n, s):
  dis=[INF]*n; dis[s]=0; vis=[False]*n; cnt=[0]*n
  q=deque([s]); vis[s]=True
  while q:
    u=q.popleft(); vis[u]=False
    for (v,w) in adj[u]:
      if dis[u]+w < dis[v]:
        dis[v]=dis[u]+w
        cnt[v]=cnt[u]+1
        if cnt[v]>=n: return False, None   # 负环
        if not vis[v]: q.append(v); vis[v]=True
  return True, dis
